//! Stamp the executable with the app icon and Windows version metadata.
//!
//! The icon is generated by `tools/icon-gen` and embedded as the resource every
//! shell surface falls back to: Explorer, the taskbar, Alt-Tab and Properties.

fn main() {
    println!("cargo:rerun-if-changed=../../assets/icon.ico");

    let mut res = winresource::WindowsResource::new();
    res.set_icon("../../assets/icon.ico")
        .set("ProductName", "剪贴助手")
        .set("FileDescription", "剪贴助手 — 剪贴板历史工具")
        .set("CompanyName", "ClipAssistant")
        .set("LegalCopyright", "© 2026 ClipAssistant")
        .set("OriginalFilename", "clipassistant.exe")
        .set("InternalName", "clipassistant");

    if let Err(err) = res.compile() {
        panic!("无法嵌入图标与版本信息: {err}");
    }
}
